const daily = {
  dateKey: dateKeyInTimeZone(),
  nodes: {
    date:document.querySelector('#dailyDate'),
    card:document.querySelector('#dailyCard'),
    image:document.querySelector('#dailyCardImage'),
    empty:document.querySelector('#dailyCard .current-card__empty'),
    name:document.querySelector('#dailyCardName'),
    position:document.querySelector('#dailyPosition'),
    meta:document.querySelector('#dailyCardMeta'),
    messageTitle:document.querySelector('#dailyMessageTitle'),
    message:document.querySelector('#dailyMessage'),
    depth:document.querySelector('#dailyDepth'),
    depthMessage:document.querySelector('#dailyDepthMessage'),
    closing:document.querySelector('#dailyArbitrioClosing'),
    depthChoices:document.querySelector('#dailyDepthChoices'),
    depthResponse:document.querySelector('#dailyDepthResponse'),
    signature:document.querySelector('#dailyArbitrioSignature'),
    again:document.querySelector('#dailyArbitrioAgain'),
    state:document.querySelector('#dailyState')
  },

  get card() { return CARDS[dailyCardIndex(this.dateKey, CARDS.length)]; },

  syncDateKey() {
    const next = dateKeyInTimeZone();
    if (next !== this.dateKey) this.dateKey = next;
  },

  get arbitrioSeedKey() { return `${dailyStorageKey(this.dateKey)}.arbitrio-seed.v1`; },

  arbitrioSeed({ create = false, renew = false } = {}) {
    try {
      const raw = localStorage.getItem(this.arbitrioSeedKey);
      if (!renew && raw) return raw;
      const seed = create || renew
        ? secureArbitrioSeed()
        : arbitrioHash(`${this.dateKey}:${this.card.canonicalId}`).toString(16);
      localStorage.setItem(this.arbitrioSeedKey, seed);
      return seed;
    } catch {
      return arbitrioHash(`${this.dateKey}:${this.card.canonicalId}`).toString(16);
    }
  },

  creation() {
    return whitTarotReading({
      cards:[this.card],
      positions:[this.dateKey],
      seed:this.arbitrioSeed(),
      scope:'carta-do-dia'
    });
  },

  renewFiction() {
    if (!this.revealed) return;
    this.arbitrioSeed({ renew:true });
    this.render();
    this.nodes.depth.open = true;
    pulseOrb();
    announce(`A consulta de ${this.card.name} foi relida sem alterar a verdade da carta.`);
  },

  get revealed() {
    try { return localStorage.getItem(dailyStorageKey(this.dateKey)) === 'revealed'; }
    catch { return false; }
  },

  reveal() {
    this.syncDateKey();
    if (this.revealed) {
      announce(`${this.card.name}. Esta é a sua Carta do Dia até a próxima meia-noite em Brasília.`);
      return;
    }
    try { localStorage.setItem(dailyStorageKey(this.dateKey), 'revealed'); } catch {}
    this.arbitrioSeed({ create:true });
    this.render();
    announce(`Carta do Dia: ${this.card.name}. Whit Taróloga abriu sua consulta de hoje.`);
  },

  render() {
    this.syncDateKey();
    const displayDate = new Intl.DateTimeFormat('pt-BR', {
      timeZone:'America/Sao_Paulo',
      weekday:'long',
      day:'2-digit',
      month:'long',
      year:'numeric'
    }).format(new Date());
    this.nodes.date.textContent = displayDate;
    const revealed = this.revealed;
    const card = this.card;
    this.nodes.card.disabled = !revealed;
    this.nodes.card.classList.toggle('is-empty', !revealed);
    this.nodes.empty.hidden = revealed;
    this.nodes.image.hidden = !revealed;

    if (!revealed) {
      this.nodes.image.removeAttribute('src');
      this.nodes.image.alt = '';
      this.nodes.card.setAttribute('aria-label', 'Carta do Dia ainda não revelada');
      this.nodes.name.textContent = 'Toque na Orbe';
      this.nodes.position.textContent = 'RITUAL DIÁRIO';
      this.nodes.meta.textContent = 'Uma carta · um ciclo · sem invertidas';
      this.nodes.messageTitle.textContent = 'Antes da palavra, a imagem.';
      this.nodes.message.textContent = 'Respire. Quando fizer sentido, toque na Orbe. A carta permanecerá até a próxima meia-noite em Brasília.';
      this.nodes.depth.hidden = true;
      this.nodes.depth.open = false;
      this.nodes.depthMessage.textContent = '';
      this.nodes.closing.textContent = '';
      renderLivingDepth(this.nodes.depthChoices, this.nodes.depthResponse, null);
      this.nodes.signature.textContent = '';
      this.nodes.state.textContent = 'Ainda não revelada neste aparelho.';
      if (currentRoute === 'carta-do-dia') orbCue.textContent = 'Revelar a aurora';
      return;
    }

    this.nodes.image.src = `assets/cards/${card.image}`;
    this.nodes.image.alt = card.name;
    this.nodes.card.setAttribute('aria-label', `${card.name}. Ampliar Carta do Dia.`);
    this.nodes.name.textContent = card.name;
    this.nodes.position.textContent = 'SÍMBOLO DE HOJE';
    this.nodes.meta.textContent = 'Uma carta · uma presença · uma direção';
    const creation = this.creation();
    this.nodes.messageTitle.textContent = creation.title;
    this.nodes.message.textContent = creationPresence(creation);
    this.nodes.depthMessage.textContent = creationStory(creation);
    this.nodes.closing.textContent = creation.closing;
    renderLivingDepth(this.nodes.depthChoices, this.nodes.depthResponse, creation);
    this.nodes.signature.textContent = creationSignature(creation);
    this.nodes.depth.hidden = false;
    this.nodes.state.textContent = 'Carta e consulta guardadas neste aparelho até o próximo ciclo de Brasília.';
    if (currentRoute === 'carta-do-dia') orbCue.textContent = 'Carta guardada';
  }
};

