export function soulVoiceSpread(cards = [], positions = [], {
  question = '',
  positioned = null,
  dialogue = null,
  human = null,
  narrative = null
} = {}) {
  const validCards = (Array.isArray(cards) ? cards : []).filter(Boolean);
