    return `<details class="consultation-tracker"${stage === 'tracking' ? ' open' : ''}>
      <summary>Acompanhar uma solicitação <span>${records.length ? `${records.length} neste aparelho` : 'protocolo privado'}</span></summary>
      ${tracking ? `<article class="consultation-tracking-result"><small>ESTADO ATUAL</small><h3>${escapeHTML(tracking.publicStatusLabel || tracking.request?.publicStatusLabel || 'Recebida')}</h3><p>${escapeHTML(tracking.request?.serviceName || tracking.serviceName || '')}</p></article>` : ''}
      ${records.length ? `<div class="consultation-records">${records.map(record => `<button type="button" data-track-record="${escapeHTML(record.protocol)}"><span><b>${escapeHTML(record.serviceName)}</b><small>${escapeHTML(record.protocol)}</small></span><em>CONSULTAR</em></button>`).join('')}</div>` : ''}
      <form data-track-form><label><span>Protocolo</span><input name="protocol" autocomplete="off" placeholder="DB-AAAAMMDD-XXXXXXXX" required></label><label><span>Código privado</span><input name="token" autocomplete="off" required></label><button type="submit">ACOMPANHAR</button></form>
      <p>O código fica somente neste aparelho. Não o publique.</p>
    </details>`;
  }

  function formMarkup() {
    const service = consultationById(selected) || services.find(item => item.id === selected);
    const value = name => escapeHTML(draft[name] || '');
    const today = new Date().toISOString().slice(0, 10);
    const days = [...new Set(slots.map(slot => slotDay(slot.start)).filter(Boolean))].slice(0, 7);
    if (!activeDay && days.length) activeDay = days[0];
    const daySlots = slots.filter(slot => slotDay(slot.start) === activeDay).slice(0, 12);
    const schedule = connection === 'ready' && slots.length ? `<section class="consultation-live-schedule">
      <div><p class="eyebrow">AGENDA REAL · HORÁRIO DE BRASÍLIA</p><h3>Escolha um horário ou informe uma preferência.</h3></div>
      <div class="consultation-days">${days.map(day => { const first = slots.find(slot => slotDay(slot.start) === day); return `<button type="button" data-consultation-day="${day}" aria-pressed="${day === activeDay}">${slotDate(first.start)}</button>`; }).join('')}</div>
      <div class="consultation-times">${daySlots.map(slot => `<button type="button" data-consultation-slot="${escapeHTML(slot.start)}" aria-pressed="${draft.slotStartAt === slot.start}">${slotTime(slot.start)}</button>`).join('')}</div>
      ${draft.slotStartAt ? `<p class="consultation-slot-choice">Escolhido: <b>${escapeHTML(slotFull(draft.slotStartAt))}</b></p>` : '<p class="consultation-slot-choice">Nenhum horário escolhido; você também pode usar os campos abaixo.</p>'}
    </section>` : `<p class="consultation-schedule-fallback">A agenda online será verificada novamente no envio. Você pode registrar uma preferência abaixo.</p>`;
    return `<section class="consultation-form-stage">
      <header><div><p class="eyebrow">SUA ESCOLHA</p><h2>${service.name}</h2><p>${money(service.priceCents)} · sem cobrança agora</p></div><button type="button" data-back-services>TROCAR</button></header>
      ${status ? `<p class="consultation-status" role="status">${escapeHTML(status)}</p>` : ''}
      <form data-consultation-form novalidate>
        ${schedule}
        <div class="consultation-preference">
          <label><span>Data preferida <small>(opcional)</small></span><input name="date" type="date" min="${today}" value="${value('date')}"></label>
          <label><span>Período</span><select name="period"><option value="">A combinar</option>${['Manhã','Tarde','Noite'].map(period => `<option${draft.period === period ? ' selected' : ''}>${period}</option>`).join('')}</select></label>
        </div>
        <label><span>Nome completo</span><input name="name" autocomplete="name" minlength="2" required value="${value('name')}"></label>
        <label><span>E-mail</span><input name="email" type="email" autocomplete="email" required value="${value('email')}"></label>
        <label><span>Telefone com DDD</span><input name="phone" type="tel" inputmode="tel" autocomplete="tel" required value="${value('phone')}"></label>
        <label><span>Pergunta ou contexto</span><textarea name="question" minlength="10" maxlength="3000" required placeholder="Não inclua senhas, documentos ou dados bancários.">${value('question')}</textarea></label>
        <div class="consultation-consents">
          <label><input name="valueConsent" type="checkbox" required${draft.valueConsent ? ' checked' : ''}><span>Confirmo o valor de ${money(service.priceCents)} e entendo que ainda não haverá cobrança.</span></label>
          <label><input name="privacyConsent" type="checkbox" required${draft.privacyConsent ? ' checked' : ''}><span>Autorizo o uso destes dados somente para administrar esta solicitação.</span></label>
          <label><input name="symbolicConsent" type="checkbox" required${draft.symbolicConsent ? ' checked' : ''}><span>Entendo que a leitura é simbólica e não substitui orientação médica, jurídica ou financeira.</span></label>
        </div>
        <button type="submit">REVISAR SOLICITAÇÃO <span aria-hidden="true">→</span></button>
      </form>
    </section>`;
  }

  function reviewMarkup() {
    const service = consultationById(selected) || services.find(item => item.id === selected);
    const preference = draft.slotStartAt ? `${slotFull(draft.slotStartAt)} · horário de Brasília` : [draft.date ? new Intl.DateTimeFormat('pt-BR', {dateStyle:'long'}).format(new Date(`${draft.date}T12:00:00`)) : '', draft.period].filter(Boolean).join(' · ') || 'A combinar';
    return `<section class="consultation-review">
      <p class="eyebrow">REVISE ANTES DE REGISTRAR</p><h2>${service.name}</h2>
      ${status ? `<p class="consultation-status" role="status">${escapeHTML(status)}</p>` : ''}
      <dl><div><dt>Valor</dt><dd>${money(service.priceCents)} · sem cobrança agora</dd></div><div><dt>Preferência</dt><dd>${escapeHTML(preference)}</dd></div><div><dt>Nome</dt><dd>${escapeHTML(draft.name)}</dd></div><div><dt>E-mail</dt><dd>${escapeHTML(draft.email)}</dd></div><div><dt>Telefone</dt><dd>${escapeHTML(draft.phone)}</dd></div><div><dt>Contexto</dt><dd>${escapeHTML(draft.question)}</dd></div></dl>
      <div><button type="button" data-confirm-consultation${busy ? ' disabled' : ''}>${busy ? 'REGISTRANDO…' : 'REGISTRAR E GERAR PROTOCOLO'}</button><button type="button" data-edit-consultation${busy ? ' disabled' : ''}>VOLTAR E EDITAR</button></div>
      ${status ? `<a href="mailto:${CONFIG.contactEmail}">USAR O E-MAIL OFICIAL</a>` : ''}
    </section>`;
  }

  function successMarkup() {
    return `<section class="consultation-success">
      <span aria-hidden="true">◇</span><p class="eyebrow">SOLICITAÇÃO REGISTRADA</p><h2>O encontro ganhou um caminho.</h2>
      <p>Guarde os dois códigos. O protocolo identifica o pedido; o código privado permite acompanhar o estado.</p>
      <div><label>Protocolo <output>${escapeHTML(success.protocol)}</output></label><button type="button" data-copy="protocol">COPIAR</button></div>
      <div><label>Código privado <output>${escapeHTML(success.trackingToken)}</output></label><button type="button" data-copy="trackingToken">COPIAR</button></div>
      <p>${escapeHTML(success.serviceName)} · ${money(success.priceCents)} · nenhuma cobrança automática.</p>
      <button type="button" data-new-consultation>NOVA SOLICITAÇÃO</button>
    </section>`;
  }

  function render() {
    const connectionLabel = connection === 'ready' ? 'REGISTRO CONECTADO' : connection === 'loading' ? 'VERIFICANDO REGISTRO' : 'RECONEXÃO NO ENVIO';
    const contact = `<p class="consultation-status"><a href="${escapeHTML(consultationContactLink(success))}">${success ? 'COMBINAR ATENDIMENTO PELO E-MAIL OFICIAL' : 'SOLICITAR CONSULTA PELO E-MAIL OFICIAL'}</a>${connection === 'ready' && !automaticEmail ? '<br>A confirmação é manual por e-mail. Depois de registrar, envie seu protocolo pelo canal oficial para combinar o atendimento.' : ''}</p>`;
    const central = (stage === 'services' ? `<section class="consultation-choice"><header><p class="eyebrow">QUATRO CAMINHOS REAIS</p><h2>Qual leitura acolhe o seu momento?</h2><p>Compare finalidade e valor antes de escolher.</p></header>${serviceCards()}</section>` : stage === 'form' ? formMarkup() : stage === 'review' ? reviewMarkup() : successMarkup()) + contact;
    root.innerHTML = `<section class="consultation-sanctuary"><div><p class="eyebrow">ATENDIMENTO HUMANO · PRIVADO</p><h2>Sua pergunta merece presença.</h2><p>Quatro leituras de R$ 50 a R$ 250. Você revisa tudo antes de registrar.</p></div><span class="consultation-connection is-${connection}"><i></i>${connectionLabel}</span></section>${central}${tracker()}`;
    bind();
  }

  function bind() {
    root.querySelectorAll('[data-service]').forEach(button => button.addEventListener('click', () => { selected = button.dataset.service; stage = 'form'; status = ''; render(); }));
    root.querySelector('[data-back-services]')?.addEventListener('click', () => { stage = 'services'; status = ''; render(); });
    root.querySelector('[data-consultation-form]')?.addEventListener('submit', prepareReview);
    root.querySelectorAll('[data-consultation-day]').forEach(button => button.addEventListener('click', () => { activeDay = button.dataset.consultationDay; draft.slotStartAt = ''; render(); }));
    root.querySelectorAll('[data-consultation-slot]').forEach(button => button.addEventListener('click', () => { draft.slotStartAt = button.dataset.consultationSlot; draft.date = ''; draft.period = ''; render(); }));
    root.querySelector('[data-edit-consultation]')?.addEventListener('click', () => { stage = 'form'; status = ''; render(); });
    root.querySelector('[data-confirm-consultation]')?.addEventListener('click', submit);
    root.querySelector('[data-new-consultation]')?.addEventListener('click', () => { selected = ''; stage = 'services'; draft = {}; pending = null; success = null; status = ''; render(); });
    root.querySelectorAll('[data-copy]').forEach(button => button.addEventListener('click', async () => {
      try { await navigator.clipboard.writeText(success?.[button.dataset.copy] || ''); announce('Código copiado.'); }
      catch { announce('Selecione o código para copiar.'); }
    }));
    root.querySelector('[data-track-form]')?.addEventListener('submit', event => {
      event.preventDefault(); const values = new FormData(event.currentTarget); track(clean(values.get('protocol')).toUpperCase(), clean(values.get('token')));
    });
    root.querySelectorAll('[data-track-record]').forEach(button => button.addEventListener('click', () => {
      const record = readRequests().find(item => item.protocol === button.dataset.trackRecord);
      if (record) track(record.protocol, record.trackingToken);
    }));
  }

  function prepareReview(event) {
    event.preventDefault();
    const form = event.currentTarget;
    const values = new FormData(form);
    const manualDate = clean(values.get('date'));
    const manualPeriod = clean(values.get('period'));
    const selectedSlot = clean(draft.slotStartAt);
    draft = {
      date:clean(values.get('date')), period:clean(values.get('period')), name:clean(values.get('name')),
      email:clean(values.get('email')), phone:clean(values.get('phone')), question:clean(values.get('question')).slice(0,3000),
      valueConsent:values.get('valueConsent') === 'on', privacyConsent:values.get('privacyConsent') === 'on', symbolicConsent:values.get('symbolicConsent') === 'on'
    };
    draft.slotStartAt = manualDate || manualPeriod ? '' : selectedSlot;
    const phone = draft.phone.replace(/\D/g, '');
    const invalid = draft.name.length < 2 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.email) || phone.length < 10 || phone.length > 15 || draft.question.length < 10 || !draft.valueConsent || !draft.privacyConsent || !draft.symbolicConsent;
    if (invalid) { status = 'Revise os campos e confirme as três declarações.'; render(); root.querySelector('[data-consultation-form] :invalid')?.focus(); return; }
    pending = { submissionId:crypto.randomUUID(), trackingToken:randomToken() };
    stage = 'review'; status = ''; render();
  }

  async function submit() {
    if (busy || !pending) return;
    const service = consultationById(selected) || services.find(item => item.id === selected);
    busy = true; status = ''; render();
    try {
      let holdToken = '';
      if (draft.slotStartAt) {
        const hold = await api({action:'hold',serviceKey:service.id,slotStartAt:draft.slotStartAt,website:''});
        holdToken = clean(hold.holdToken);
      }
      const result = await api({
        action:'submit', holdToken, submissionId:pending.submissionId, trackingToken:pending.trackingToken,
        serviceKey:service.id, preferredDate:draft.date, preferredPeriod:draft.period,
        name:draft.name, email:draft.email, phone:draft.phone, questionContext:draft.question,
        acceptTerms:true, acceptPrivacy:true, acceptSymbolic:true, marketingOptIn:false, website:''
      });
      success = { protocol:clean(result.protocol) || pending.submissionId, trackingToken:pending.trackingToken, serviceName:service.name, serviceId:service.id, priceCents:Number(result.priceCents) || service.priceCents };
      const records = readRequests().filter(record => record.protocol !== success.protocol);
      writeRequests([{...success, createdAt:new Date().toISOString()}, ...records]);
      stage = 'success'; pending = null; draft = {}; announce('Solicitação registrada. Guarde o protocolo e o código privado.');
    } catch (error) {
      status = errorMessage(error);
      if (['SLOT_UNAVAILABLE','INVALID_SLOT','HOLD_EXPIRED'].includes(clean(error?.code || error?.message))) {
        draft.slotStartAt = ''; stage = 'form'; connect();
      }
    }
    busy = false; render();
  }

  async function track(protocol, trackingToken) {
    if (!/^DB-[0-9]{8}-[A-Z0-9]{8}$/.test(protocol) || !/^[A-Za-z0-9_-]{24,96}$/.test(trackingToken)) {
      status = 'Revise o protocolo e o código privado.'; stage = stage === 'success' ? 'success' : stage; return render();
    }
    status = 'Consultando o registro seguro…'; render();
    try { tracking = await api({ action:'status', protocol, trackingToken, website:'' }); status = ''; announce('Estado da solicitação atualizado.'); }
    catch (error) { status = errorMessage(error); }
    render();
  }

  async function connect() {
    try {
      const result = await api();
      if (result?.environment !== 'staging' || result?.rules?.realBilling !== false || !Array.isArray(result.services)) throw new Error('INVALID_CATALOG');
      automaticEmail = result.notifications?.providerConfigured === true;
      const remote = CONSULTATION_SERVICES.map(local => {
        const found = result.services.find(item => clean(item.service_key) === local.id);
        const price = Number(found?.price_brl_cents);
        return Number.isInteger(price) && price > 0 ? {...local, priceCents:price} : local;
      });
      services = Object.freeze(remote);
      slots = (Array.isArray(result.slots) ? result.slots : []).map(slot => ({start:clean(slot.slot_start_at || slot.start),end:clean(slot.slot_end_at || slot.end)})).filter(slot => slot.start && new Date(slot.start) > new Date());
      if (draft.slotStartAt && !slots.some(slot => slot.start === draft.slotStartAt)) draft.slotStartAt = '';
      activeDay = slotDay(draft.slotStartAt) || activeDay || slotDay(slots[0]?.start);
      connection = 'ready';
    } catch { connection = 'offline'; slots = []; }
    render();
  }

  function activate() {
    if (!started) { started = true; render(); connect(); }
  }

  return { activate };
}

import { dateKeyInTimeZone } from '../lib/daily-card.js';

const ENTRIES_KEY = 'divina-bruxa-3.diario.entradas.v1';
const DRAFT_KEY = 'divina-bruxa-3.diario.rascunho.v1';
const normalize = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

function loadJson(key, fallback) {
  try { return JSON.parse(localStorage.getItem(key)) ?? fallback; }
  catch { return fallback; }
}

function safeEntries() {
  const value = loadJson(ENTRIES_KEY, []);
  return Array.isArray(value) ? value
    .filter(entry => entry && typeof entry.id === 'string' && typeof entry.title === 'string' && typeof entry.body === 'string')
    .slice(-500)
    .map(entry => ({
      id:entry.id.slice(0, 100),
      title:entry.title.slice(0, 90),
      body:entry.body.slice(0, 8000),
      date:/^\d{4}-\d{2}-\d{2}$/.test(entry.date) ? entry.date : dateKeyInTimeZone(),
      mood:typeof entry.mood === 'string' ? entry.mood.slice(0, 40) : '',
      tags:Array.isArray(entry.tags) ? entry.tags.filter(tag => typeof tag === 'string').slice(0, 12).map(tag => tag.slice(0, 50)) : [],
      favorite:Boolean(entry.favorite),
      createdAt:typeof entry.createdAt === 'string' ? entry.createdAt : '',
      updatedAt:typeof entry.updatedAt === 'string' ? entry.updatedAt : ''
    })) : [];
}

export function createJournalWorld({ announce }) {
  const nodes = {
    form:document.querySelector('#journalForm'),
    id:document.querySelector('#journalId'),
    title:document.querySelector('#journalEntryTitle'),
    body:document.querySelector('#journalBody'),
    date:document.querySelector('#journalDate'),
    mood:document.querySelector('#journalMood'),
    tags:document.querySelector('#journalTags'),
    favorite:document.querySelector('#journalFavorite'),
    clear:document.querySelector('#journalClear'),
    draft:document.querySelector('#journalDraftState'),
    export:document.querySelector('#journalExport'),
    search:document.querySelector('#journalSearch'),
    entries:document.querySelector('#journalEntries')
  };
  let entries = safeEntries();

  function persistEntries() {
    try { localStorage.setItem(ENTRIES_KEY, JSON.stringify(entries)); } catch {}
  }

  function formValue() {
    return {
      id:nodes.id.value,
      title:nodes.title.value,
      body:nodes.body.value,
      date:nodes.date.value,
      mood:nodes.mood.value,
      tags:nodes.tags.value,
      favorite:nodes.favorite.checked
    };
  }

  function saveDraft() {
    const draft = formValue();
    try { localStorage.setItem(DRAFT_KEY, JSON.stringify(draft)); nodes.draft.textContent = 'Rascunho salvo somente neste aparelho.'; }
    catch { nodes.draft.textContent = 'Rascunho mantido apenas nesta aba.'; }
  }

  function clearForm({ keepDraft = false } = {}) {
    nodes.form.reset();
    nodes.id.value = '';
    nodes.date.value = dateKeyInTimeZone();
    if (!keepDraft) {
      try { localStorage.removeItem(DRAFT_KEY); } catch {}
    }
    nodes.draft.textContent = 'Nova página privada.';
  }

  function restoreDraft() {
    const draft = loadJson(DRAFT_KEY, null);
    if (!draft || typeof draft !== 'object') return clearForm({ keepDraft:true });
    nodes.id.value = typeof draft.id === 'string' ? draft.id : '';
    nodes.title.value = typeof draft.title === 'string' ? draft.title : '';
    nodes.body.value = typeof draft.body === 'string' ? draft.body : '';
    nodes.date.value = /^\d{4}-\d{2}-\d{2}$/.test(draft.date) ? draft.date : dateKeyInTimeZone();
    nodes.mood.value = typeof draft.mood === 'string' ? draft.mood : '';
    nodes.tags.value = typeof draft.tags === 'string' ? draft.tags : '';
    nodes.favorite.checked = Boolean(draft.favorite);
    nodes.draft.textContent = nodes.title.value || nodes.body.value ? 'Rascunho local retomado.' : 'Nova página privada.';
  }

  function render() {
    const query = normalize(nodes.search.value.trim());
    const visible = [...entries]
      .filter(entry => !query || normalize(`${entry.title} ${entry.body} ${entry.mood} ${(entry.tags || []).join(' ')}`).includes(query))
      .sort((a, b) => `${b.date}:${b.updatedAt}`.localeCompare(`${a.date}:${a.updatedAt}`));
    const fragment = document.createDocumentFragment();
    visible.forEach(entry => {
      const article = document.createElement('article');
      article.className = 'journal-entry';
      const meta = document.createElement('div');
      meta.className = 'journal-entry__meta';
      const date = document.createElement('span');
      date.textContent = `${entry.favorite ? '★ ' : ''}${entry.date}`;
      const mood = document.createElement('span');
      mood.textContent = entry.mood || 'Sem rótulo';
      meta.append(date, mood);
      const title = document.createElement('h3');
      title.textContent = entry.title;
      const preview = document.createElement('p');
      preview.className = 'journal-entry__preview';
      preview.textContent = entry.body.length > 260 ? `${entry.body.slice(0, 260)}…` : entry.body;
      const tags = document.createElement('div');
      tags.className = 'journal-entry__tags';
      (entry.tags || []).forEach(tag => {
        const span = document.createElement('span');
        span.textContent = tag;
        tags.append(span);
      });
      const actions = document.createElement('div');
      actions.className = 'journal-entry__actions';
      const edit = document.createElement('button');
      edit.type = 'button';
      edit.textContent = 'Abrir';
      edit.addEventListener('click', () => editEntry(entry));
      const remove = document.createElement('button');
      remove.type = 'button';
      remove.textContent = 'Excluir';
      remove.addEventListener('click', () => armDelete(remove, entry.id));
      actions.append(edit, remove);
      article.append(meta, title, preview, tags, actions);
      fragment.append(article);
    });
    if (!visible.length) {
      const empty = document.createElement('p');
      empty.className = 'journal-empty';
      empty.textContent = entries.length ? 'Nenhum registro encontrou esse termo.' : 'A primeira página ainda está em branco.';
      fragment.append(empty);
    }
    nodes.entries.replaceChildren(fragment);
  }

  function editEntry(entry) {
    nodes.id.value = entry.id;
    nodes.title.value = entry.title;
    nodes.body.value = entry.body;
    nodes.date.value = entry.date;
    nodes.mood.value = entry.mood || '';
    nodes.tags.value = (entry.tags || []).join(', ');
    nodes.favorite.checked = Boolean(entry.favorite);
    saveDraft();
    nodes.title.focus();
    announce(`Registro ${entry.title} aberto para edição.`);
  }

  function armDelete(button, id) {
    if (button.dataset.armed !== 'true') {
      button.dataset.armed = 'true';
      button.textContent = 'Confirmar exclusão';
      setTimeout(() => { if (button.isConnected) { button.dataset.armed = 'false'; button.textContent = 'Excluir'; } }, 4500);
      return;
    }
    const entry = entries.find(item => item.id === id);
    entries = entries.filter(item => item.id !== id);
    persistEntries();
    render();
    announce(`${entry?.title || 'Registro'} foi excluído deste aparelho.`);
  }

  nodes.form.addEventListener('input', saveDraft);
  nodes.form.addEventListener('submit', event => {
    event.preventDefault();
    const value = formValue();
    const now = new Date().toISOString();
    const id = value.id || crypto.randomUUID?.() || `entry-${Date.now()}`;
    const entry = {
      id,
      title:value.title.trim(),
      body:value.body.trim(),
      date:value.date,
      mood:value.mood,
      tags:value.tags.split(',').map(tag => tag.trim()).filter(Boolean).slice(0, 12),
      favorite:value.favorite,
      createdAt:entries.find(item => item.id === id)?.createdAt || now,
      updatedAt:now
    };
    entries = [...entries.filter(item => item.id !== id), entry];
    persistEntries();
    clearForm();
    render();
    announce(`${entry.title} foi guardado no Diário deste aparelho.`);
  });
  nodes.clear.addEventListener('click', () => clearForm());
  nodes.search.addEventListener('input', render);
  nodes.export.addEventListener('click', () => {
    const blob = new Blob([JSON.stringify({ exportedAt:new Date().toISOString(), entries }, null, 2)], { type:'application/json' });
    const href = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = href;
    link.download = `divina-bruxa-diario-${dateKeyInTimeZone()}.json`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(href), 1000);
    announce('Cópia do Diário preparada para download.');
  });

  restoreDraft();
  render();
  return Object.freeze({ activate:render, entryCount:() => entries.length });
}

import { LIBRARY_GUIDES } from '../data/library.js';

const normalize = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

export function cardPublicHref(card) {
  if (card.arcanaCode === 'major') return `carta-${card.canonicalId}.html`;
  return `carta-${card.canonicalId.replace(/^\d{2}-/, '')}.html`;
}

export function createLibraryWorld({ cards, showCard }) {
  const nodes = {
    search:document.querySelector('#librarySearch'),
    filters:document.querySelector('#libraryFilters'),
    count:document.querySelector('#libraryCount'),
    results:document.querySelector('#libraryResults')
  };
  let filter = 'all';

  function cardMatches(card, query) {
    const searchable = normalize(`${card.name} ${card.names.en} ${card.names.es} ${card.arcana} ${card.suit} ${card.element} ${card.correspondences?.astrological || ''} ${card.correspondences?.domain || ''}`);
    return searchable.includes(query);
  }

  function allowedCard(card) {
    if (filter === 'all') return true;
    if (filter === 'major') return card.arcanaCode === 'major';
    return card.suitCode === filter;
  }

  function render() {
    const query = normalize(nodes.search.value.trim());
    const showGuides = filter === 'all' || filter === 'guides';
    const visibleCards = filter === 'guides' ? [] : cards.filter(card => allowedCard(card) && (!query || cardMatches(card, query)));
    const visibleGuides = showGuides ? LIBRARY_GUIDES.filter(guide => !query || normalize(`${guide.title} ${guide.category} ${guide.description}`).includes(query)) : [];
    const fragment = document.createDocumentFragment();

    visibleGuides.forEach(guide => {
      const article = document.createElement('article');
      article.className = 'library-item library-item--guide';
      const link = document.createElement('a');
      link.href = guide.href;
      link.innerHTML = `<small>${guide.category}</small><h3>${guide.title}</h3><p>${guide.description}</p>`;
      article.append(link);
      fragment.append(article);
    });

    visibleCards.forEach(card => {
      const article = document.createElement('article');
      article.className = 'library-item';
      const button = document.createElement('button');
      button.type = 'button';
      button.setAttribute('aria-label', `Abrir ${card.name}`);
      const image = new Image();
      image.src = `assets/cards/${card.image}`;
      image.alt = '';
      image.loading = 'lazy';
      image.width = 220;
      image.height = 330;
      const title = document.createElement('h3');
      title.textContent = card.name;
      const description = document.createElement('p');
      description.textContent = `${card.arcana} · ${card.element} · ${card.suit}`;
      const more = document.createElement('small');
      more.textContent = 'Ver carta e página pública';
      button.append(image, title, description, more);
      button.addEventListener('click', () => showCard(card, 'BIBLIOTECA · CARTA DIRETA', cardPublicHref(card)));
      article.append(button);
      fragment.append(article);
    });

    if (!visibleCards.length && !visibleGuides.length) {
      const empty = document.createElement('p');
      empty.className = 'library-empty';
      empty.textContent = 'Nenhum fio encontrou esse termo. Tente um nome, elemento, naipe ou pergunta diferente.';
      fragment.append(empty);
    }
    nodes.results.replaceChildren(fragment);
    nodes.count.textContent = `${visibleGuides.length} guias · ${visibleCards.length} cartas`;
  }

  nodes.search.addEventListener('input', render);
  nodes.filters.querySelectorAll('[data-filter]').forEach(button => button.addEventListener('click', () => {
    filter = button.dataset.filter;
    nodes.filters.querySelectorAll('[data-filter]').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
    render();
  }));

  render();
  return Object.freeze({ activate:render });
}

import { MUSIC_RELEASES, SPOTIFY_ARTIST } from '../data/media.js';

export function createMusicWorld({ announce }) {
  const releases = document.querySelector('#musicReleases');
  const player = document.querySelector('#musicPlayer');
  let active = '';
  let ready = false;

  function renderReleases() {
    releases.replaceChildren(...MUSIC_RELEASES.map(release => {
      const article = document.createElement('article');
      article.className = `music-release${release.id === active ? ' is-active' : ''}`;
      article.innerHTML = `
        <span aria-hidden="true">${release.mark}</span>
        <div><small>ÁLBUM · ${release.year} · ${release.tracks} FAIXAS</small><h2>${release.title}</h2><p>${release.description}</p><b>${release.artist}</b></div>
        <button type="button" data-album="${release.id}" aria-pressed="${release.id === active}">${release.id === active ? 'PLAYER ABERTO' : 'OUVIR NO SPOTIFY'}</button>`;
      return article;
    }));
  }

  function open(release) {
    active = release.id;
    renderReleases();
    player.replaceChildren();
    const top = document.createElement('div');
    top.className = 'music-player__top';
    top.innerHTML = `<p><small>TOCANDO SOMENTE POR SUA ESCOLHA</small><b>${release.title}</b></p><button type="button" id="closeMusicPlayer">Fechar player</button>`;
    const frame = document.createElement('iframe');
    frame.title = `Spotify — ${release.title}`;
    frame.src = `https://open.spotify.com/embed/album/${release.id}?utm_source=generator&theme=0`;
    frame.width = '100%';
    frame.height = '352';
    frame.loading = 'lazy';
    frame.allow = 'clipboard-write; encrypted-media; fullscreen; picture-in-picture';
    frame.referrerPolicy = 'strict-origin-when-cross-origin';
    player.append(top, frame);
    top.querySelector('button').addEventListener('click', close);
    announce(`Player oficial de ${release.title} aberto.`);
  }

  function close() {
    active = '';
    renderReleases();
    player.innerHTML = `<p>O player foi fechado e o áudio interrompido.</p><a href="${SPOTIFY_ARTIST}" target="_blank" rel="noopener noreferrer">VER HÉRCULES DX NO SPOTIFY ↗</a>`;
    announce('Player fechado.');
  }

  function activate() {
    if (ready) return;
    ready = true;
    renderReleases();
    releases.addEventListener('click', event => {
      const button = event.target.closest('[data-album]');
      if (!button) return;
      const release = MUSIC_RELEASES.find(item => item.id === button.dataset.album);
      if (release) open(release);
    });
  }

  return { activate, deactivate:close };
}

import { CONFIG } from '../data/config.js';
import { amazonSearchUrl, STORE_CATEGORIES, STORE_PRODUCTS } from '../data/store.js';

const FAVORITES_KEY = 'divina-bruxa-3.store-favorites.v1';

function readFavorites() {
  try {
    const value = JSON.parse(localStorage.getItem(FAVORITES_KEY) || '[]');
    return new Set(Array.isArray(value) ? value.filter(id => STORE_PRODUCTS.some(product => product.id === id)) : []);
  } catch { return new Set(); }
}

export function createStoreWorld({ announce }) {
  const search = document.querySelector('#storeSearch');
  const categories = document.querySelector('#storeCategories');
  const favoriteToggle = document.querySelector('#storeFavorites');
  const count = document.querySelector('#storeCount');
  const grid = document.querySelector('#storeGrid');
  let category = 'Tudo';
  let onlyFavorites = false;
  let favorites = readFavorites();
  let ready = false;

  function saveFavorites() {
    try { localStorage.setItem(FAVORITES_KEY, JSON.stringify([...favorites])); } catch {}
  }

  function filtered() {
    const query = search.value.trim().toLocaleLowerCase('pt-BR');
    return STORE_PRODUCTS.filter(product => {
      const inCategory = category === 'Tudo' || product.category === category;
      const isFavorite = !onlyFavorites || favorites.has(product.id);
      const haystack = `${product.name} ${product.category} ${product.description} ${product.tags.join(' ')}`.toLocaleLowerCase('pt-BR');
      return inCategory && isFavorite && (!query || haystack.includes(query));
    });
  }

  function renderProducts() {
    const products = filtered();
    count.textContent = `${products.length} ${products.length === 1 ? 'escolha encontrada' : 'escolhas encontradas'}`;
    favoriteToggle.querySelector('b').textContent = String(favorites.size);
    favoriteToggle.setAttribute('aria-pressed', String(onlyFavorites));
    grid.replaceChildren(...products.map(product => {
      const article = document.createElement('article');
      article.className = 'store-card';
      article.innerHTML = `
        <span class="store-card__symbol" aria-hidden="true">${product.symbol}</span>
        <small>${product.category}${product.featured ? ' · DESTAQUE' : ''}</small>
        <h2>${product.name}</h2>
        <p>${product.description}</p>
        <div>
          <button type="button" data-favorite="${product.id}" aria-pressed="${favorites.has(product.id)}" aria-label="${favorites.has(product.id) ? 'Remover' : 'Adicionar'} ${product.name} dos favoritos">${favorites.has(product.id) ? '♥' : '♡'}</button>
          <a href="${amazonSearchUrl(product.search, CONFIG.amazonAssociateTag)}" target="_blank" rel="sponsored noopener noreferrer">VER OPÇÕES <span aria-hidden="true">↗</span></a>
        </div>`;
      return article;
    }));
    if (!products.length) {
      const empty = document.createElement('p');
      empty.className = 'world-empty';
      empty.textContent = onlyFavorites ? 'Nenhuma escolha favorita corresponde a este filtro.' : 'Nenhuma escolha corresponde a esta busca.';
      grid.append(empty);
    }
  }

  function activate() {
    if (ready) return renderProducts();
    ready = true;
    categories.replaceChildren(...STORE_CATEGORIES.map(name => {
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = name;
      button.dataset.category = name;
      button.setAttribute('aria-pressed', String(name === category));
      return button;
    }));
    categories.addEventListener('click', event => {
      const button = event.target.closest('[data-category]');
      if (!button) return;
      category = button.dataset.category;
      categories.querySelectorAll('button').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
      renderProducts();
    });
    search.addEventListener('input', renderProducts);
    favoriteToggle.addEventListener('click', () => { onlyFavorites = !onlyFavorites; renderProducts(); });
    grid.addEventListener('click', event => {
      const button = event.target.closest('[data-favorite]');
      if (!button) return;
      const id = button.dataset.favorite;
      if (favorites.has(id)) favorites.delete(id); else favorites.add(id);
      saveFavorites();
      renderProducts();
      const product = STORE_PRODUCTS.find(item => item.id === id);
      announce(`${product?.name || 'Escolha'} ${favorites.has(id) ? 'guardada nos favoritos' : 'removida dos favoritos'}.`);
    });
    renderProducts();
  }

  return { activate };
}
